    private static string TraceparentOf(Activity activity) =>
        $"00-{activity.TraceId}-{activity.SpanId}-{(int)activity.ActivityTraceFlags:x2}";

    private static ActivityListener RecordAllActivities()
    {
        var listener = new ActivityListener
        {
            ShouldListenTo = _ => true,
            Sample = (ref ActivityCreationOptions<ActivityContext> _) =>
                ActivitySamplingResult.AllDataAndRecorded,
        };
        ActivitySource.AddActivityListener(listener);
        return listener;
    }

    private static async Task<Dictionary<string, string>> CallCapturingHeadersAsync(
        IAuthenticator? auth = null
    )
    {
        var client = new CapturingApiClient();
        var api = new TestableApi(client, "http://localhost", auth);
        await api.CallAsync<JsonNode>(
            "GET",
            "/test/echo",
            new Dictionary<string, object?>(),
            new Dictionary<string, string>(),
            null,
            ["application/json"],
            "application/json"
        );
        return client.CapturedHeaders;
    }

