    [Fact]
    public async Task BhvAuthintegration005SecurityNoneOperationSuppressesClientAuthenticator()
    {
        var client = new CapturingApiClient();
        var clientAuth = new TestAuthenticator(
            headers: new Dictionary<string, string>
            {
                { "Authorization", "Bearer client-secret" },
                { "api-key", "client-api-key" },
            },
            queryParams: new Dictionary<string, string> { { "api_key", "client-api-key" } },
            cookies: new Dictionary<string, string> { { "session", "client-cookie" } }
        );
        var config = new Configuration("http://localhost");
        var api = new StoreApi(client, config, clientAuth);

        try
        {
            // getInventory is security:[]; the captured request is what matters.
            await api.GetInventoryAsync();
        }
        catch (OpenAPIException)
        {
            // The captured request is asserted regardless of the response shape.
        }

        Assert.False(
            client.CapturedHeaders.ContainsKey("Authorization"),
            "security:[] operation must NOT carry the client Authorization header"
        );
        Assert.False(
            client.CapturedHeaders.ContainsKey("api-key"),
            "security:[] operation must NOT carry the client api-key header"
        );
        Assert.False(
            client.CapturedHeaders.ContainsKey("Cookie"),
            "security:[] operation must NOT carry the client auth cookie"
        );
        Assert.DoesNotContain("api_key=", client.CapturedUrl!.ToString(), StringComparison.Ordinal);
    }

