    /// <summary>One request a paged-list server saw: the path, the decoded query and the headers.</summary>
    private sealed record SeenRequest(
        string Path,
        IReadOnlyDictionary<string, string> Query,
        IReadOnlyDictionary<string, string> Headers
    )
    {
        public string? Param(string name) =>
            Query.TryGetValue(name, out string? value) ? value : null;

        public string? Header(string name) => HeaderOf(Headers, name);
    }

    /// <summary>What a paged-list server answers: a status, a JSON body, extra headers and a delay before it answers.</summary>
    private sealed record Reply(
        int Status,
        string Body,
        IReadOnlyDictionary<string, string>? Headers = null,
        int DelayMilliseconds = 0
    )
    {
        public static Reply Ok(string body, IReadOnlyDictionary<string, string>? headers = null) =>
            new(200, body, headers);

        public static Reply Failing(int status) =>
            new(status, "{}", new Dictionary<string, string> { ["Retry-After"] = "0" });

        public Reply After(int milliseconds) => this with { DelayMilliseconds = milliseconds };
    }

    /// <summary>
    /// An in-process server whose answer depends on the request it gets and on how many it has
    /// had, which the shared mock cannot do. It records every request in arrival order.
    /// </summary>
    private sealed class PagedServer : IDisposable
    {
        private readonly RawServer _server;
        private readonly List<SeenRequest> _seen = [];

        public PagedServer(Func<SeenRequest, int, Reply> handler)
        {
            _server = RawServer.Serve(
                async (_, socket, _, head) =>
                {
                    SeenRequest request = Parse(head);
                    int number;
                    lock (_seen)
                    {
                        _seen.Add(request);
                        number = _seen.Count;
                    }
                    Reply reply = handler(request, number);
                    if (reply.DelayMilliseconds > 0)
                    {
                        await Task.Delay(reply.DelayMilliseconds);
                    }
                    byte[] bytes = Encoding.UTF8.GetBytes(reply.Body);
                    List<string> headers =
                    [
                        "Content-Type: application/json",
                        "Content-Length: " + bytes.Length,
                    ];
                    foreach (
                        KeyValuePair<string, string> extra in reply.Headers
                            ?? new Dictionary<string, string>()
                    )
                    {
                        headers.Add(extra.Key + ": " + extra.Value);
                    }
                    await RawServer.HeadAsync(socket, reply.Status, [.. headers]);
                    await RawServer.WriteBytesAsync(socket, bytes);
                }
            );
        }

        public string Url => _server.Url("");

        public IReadOnlyList<SeenRequest> Seen
        {
            get
            {
                lock (_seen)
                {
                    return [.. _seen];
                }
            }
        }

        public void Dispose() => _server.Dispose();

        private static SeenRequest Parse(string head)
        {
            string[] lines = head.Split("\r\n", StringSplitOptions.RemoveEmptyEntries);
            string target = lines[0].Split(' ')[1];
            int mark = target.IndexOf('?', StringComparison.Ordinal);
            Dictionary<string, string> query = [];
            if (mark >= 0)
            {
                foreach (string pair in target[(mark + 1)..].Split('&'))
                {
                    int eq = pair.IndexOf('=', StringComparison.Ordinal);
                    string key = eq < 0 ? pair : pair[..eq];
                    string value = eq < 0 ? "" : pair[(eq + 1)..];
                    query[Uri.UnescapeDataString(key)] = Uri.UnescapeDataString(
                        value.Replace('+', ' ')
                    );
                }
            }
            Dictionary<string, string> headers = new(StringComparer.OrdinalIgnoreCase);
            foreach (string line in lines.Skip(1))
            {
                int colon = line.IndexOf(':', StringComparison.Ordinal);
                if (colon > 0)
                {
                    headers[line[..colon]] = line[(colon + 1)..].Trim();
                }
            }
            return new SeenRequest(mark >= 0 ? target[..mark] : target, query, headers);
        }
    }

    /// <summary>One pet as a JSON object.</summary>
    private static string PetJson(string name) =>
        "{\"id\":1,\"name\":\"" + name + "\",\"photoUrls\":[]}";

    /// <summary>A catalog page: the pets of page <paramref name="page"/> of <paramref name="size"/>, and the cursor of the page after it.</summary>
    private static string CatalogBody(int page, int size, int pages)
    {
        string items = string.Join(
            ",",
            Enumerable.Range(0, size).Select(i => PetJson($"p{page}-{i}"))
        );
        string next = page + 1 < pages ? $",\"next_cursor\":\"c{page + 1}\"" : "";
        return "{\"items\":[" + items + "]" + next + "}";
    }

    /// <summary>A catalog of <paramref name="pages"/> pages of <paramref name="size"/> pets; the cursor of page n is "c" followed by n.</summary>
    private static PagedServer CatalogServer(int pages, int size)
    {
        return new PagedServer(
            (request, _) =>
            {
                string? cursor = request.Param("cursor");
                int page = cursor is null
                    ? 0
                    : int.Parse(cursor[1..], System.Globalization.CultureInfo.InvariantCulture);
                return Reply.Ok(CatalogBody(page, size, pages));
            }
        );
    }

    private static PetApi PetApiFor(
        PagedServer server,
        int maxRetries = 0,
        IReadOnlyDictionary<string, string>? defaultHeaders = null,
        IAuthenticator? authenticator = null
    )
    {
        ConfigurationBuilder configuration = Configuration.Builder().BaseUrl(server.Url);
        foreach (
            KeyValuePair<string, string> header in defaultHeaders
                ?? new Dictionary<string, string>()
        )
        {
            configuration = configuration.DefaultHeader(header.Key, header.Value);
        }
        return new PetApi(
            new DefaultApiClient(TransportOptions.Builder().MaxRetries(maxRetries).Build()),
            configuration.Build(),
            authenticator
        );
    }

    private static async Task<List<string>> NamesAsync(IAsyncEnumerable<Pet> pets)
    {
        List<string> names = [];
        await foreach (Pet pet in pets)
        {
            names.Add(pet.Name);
        }
        return names;
    }

    /// <summary>A feed page: one pet and a Link header that names the next page, or none on the last.</summary>
    private static PagedServer FeedServer(int pages, Func<int, string> link)
    {
        return new PagedServer(
            (request, _) =>
            {
                string? page = request.Param("page");
                int index = page is null
                    ? 0
                    : int.Parse(page, System.Globalization.CultureInfo.InvariantCulture);
                Dictionary<string, string> headers =
                    index + 1 < pages ? new() { ["Link"] = link(index + 1) } : [];
                return Reply.Ok("[" + PetJson($"f{index}") + "]", headers);
            }
        );
    }

    private static PagedServer SameOriginFeed(int pages)
    {
        PagedServer? self = null;
        self = FeedServer(
            pages,
            next => $"<{self!.Url}/pet/feed?page={next}&secret=s3>; rel=\"next\""
        );
        return self;
    }

    /// <summary>The pets from index <paramref name="from"/> up to <paramref name="to"/>, as JSON items.</summary>
    private static string PetsJson(int from, int to)
    {
        return string.Join(",", Enumerable.Range(from, to - from).Select(i => PetJson($"p{i}")));
    }

    /// <summary>Five pets in total, served two at a time from the offset the request names.</summary>
    private static PagedServer OffsetServer()
    {
        return new PagedServer(
            (request, _) =>
            {
                string? offset = request.Param("offset");
                int from = offset is null
                    ? 0
                    : int.Parse(offset, System.Globalization.CultureInfo.InvariantCulture);
                return Reply.Ok(
                    "{\"items\":[" + PetsJson(Math.Min(from, 5), Math.Min(from + 2, 5)) + "]}"
                );
            }
        );
    }

    /// <summary>Five pets in total, two to a numbered page, from page 1.</summary>
    private static PagedServer PageNumberServer()
    {
        return new PagedServer(
            (request, _) =>
            {
                string? page = request.Param("page");
                int index = page is null
                    ? 1
                    : int.Parse(page, System.Globalization.CultureInfo.InvariantCulture);
                int from = (index - 1) * 2;
                return Reply.Ok(
                    "{\"items\":["
                        + PetsJson(Math.Min(from, 5), Math.Min(from + 2, 5))
                        + "],\"has_more\":true}"
                );
            }
        );
    }

    /// <summary>Five pets in total, two to a page, each page with the id of its last pet and a has_more flag.</summary>
    private static PagedServer AfterServer()
    {
        return new PagedServer(
            (request, _) =>
            {
                string? after = request.Param("starting_after");
                int from = after is null
                    ? 0
                    : int.Parse(after[1..], System.Globalization.CultureInfo.InvariantCulture) + 1;
                int to = Math.Min(from + 2, 5);
                string more = to < 5 ? "true" : "false";
                return Reply.Ok(
                    "{\"data\":["
                        + PetsJson(from, to)
                        + "],\"has_more\":"
                        + more
                        + ",\"last_id\":\"p"
                        + (to - 1)
                        + "\"}"
                );
            }
        );
    }

    /// <summary>Three pets, one to a page, each page with the URL of the next one in the body.</summary>
    private static PagedServer NextUrlServer(int pages)
    {
        PagedServer? self = null;
        self = new PagedServer(
            (request, _) =>
            {
                string? p = request.Param("p");
                int index = p is null
                    ? 0
                    : int.Parse(p, System.Globalization.CultureInfo.InvariantCulture);
                string next =
                    index + 1 < pages
                        ? ",\"next_url\":\"" + self!.Url + "/pet/next?p=" + (index + 1) + "\""
                        : "";
                return Reply.Ok("{\"items\":[" + PetJson($"f{index}") + "]" + next + "}");
            }
        );
        return self;
    }

    private static List<string?> ParamsSeen(PagedServer server, string name)
    {
        return [.. server.Seen.Select(request => request.Param(name))];
    }

