    [Fact]
    public async Task BhvPagination007ALinkHeaderOperationFollowsRelNextAndEndsWhenItIsAbsent()
    {
        using PagedServer server = SameOriginFeed(3);

        Assert.Equal(
            ["f0", "f1", "f2"],
            await NamesAsync(PetApiFor(server).ListPetFeedPagesAsync())
        );
        Assert.Equal(new List<string?> { null, "1", "2" }, ParamsSeen(server, "page"));
        Assert.Equal("/pet/feed", server.Seen[2].Path);

        Assert.Equal("/a,b?x=1", LinkHeader.Next("</a,b?x=1>; rel=\"next\""));
        Assert.Equal("/two", LinkHeader.Next("</one>; rel=\"prev\", </two>; rel=\"next\""));
        Assert.Equal(
            "/second",
            LinkHeader.Next("</first>; rel=\"prev\"; title=\"a, b\", </second>; REL=NEXT")
        );
        Assert.Equal(
            "/first",
            LinkHeader.Next("</first>; rel=\"prev next\", </second>; rel=\"next\"")
        );
        Assert.Null(LinkHeader.Next("</one>; rel=\"prev\", </last>; rel=\"last\""));
        Assert.Null(LinkHeader.Next("not a link header"));
    }

    [Fact]
