    {
        using PagedServer elsewhere = new((_, _) => Reply.Ok("[" + PetJson("stolen") + "]"));
        using PagedServer origin = new(
            (_, _) =>
                Reply.Ok(
                    "[" + PetJson("f0") + "]",
                    new Dictionary<string, string>
                    {
                        ["Link"] = $"<{elsewhere.Url}/pet/feed?page=1>; rel=\"next\"",
                    }
                )
        );
        PetApi api = PetApiFor(
            origin,
            defaultHeaders: new Dictionary<string, string> { ["Authorization"] = "Bearer secret" }
