    [Fact]
    public async Task BhvPagination018StoppingEarlySendsNoFurtherRequestAndLeavesNothingToClose()
    {
        using PagedServer server = CatalogServer(3, 2);

        await foreach (Pet pet in PetApiFor(server).ListPetCatalogPagesAsync())
        {
            Assert.Equal("p0-0", pet.Name);
            break;
        }
        Assert.Single(server.Seen);

        int read = 0;
        await foreach (Pet pet in PetApiFor(server).ListPetCatalogPagesAsync())
        {
            Assert.NotNull(pet);
            if (++read == 3)
            {
                break;
            }
        }
        Assert.Equal(3, server.Seen.Count);
        Assert.False(typeof(IAsyncDisposable).IsAssignableFrom(typeof(Paginator<Pet, string?>)));
        Assert.False(typeof(IDisposable).IsAssignableFrom(typeof(Paginator<Pet, string?>)));
    }

    [Fact]
    public async Task BhvPagination019CancellingMidIterationAbortsTheInFlightPageRequestAndIsNotReportedAsATimeout()
    {
        using PagedServer server = new(
            (request, _) =>
                request.Param("cursor") is null
                    ? Reply.Ok(CatalogBody(0, 1, 2))
                    : Reply.Ok(CatalogBody(1, 1, 2)).After(8000)
        );
        using CancellationTokenSource cancel = new();
        PetApi api = new(
            new DefaultApiClient(TransportOptions.Builder().MaxRetries(0).Timeout(20000).Build()),
            Configuration.Builder().BaseUrl(server.Url).Build()
        );

        Stopwatch clock = Stopwatch.StartNew();
        Task<List<string>> reading = NamesAsync(api.ListPetCatalogPagesAsync(null, cancel.Token));
        while (server.Seen.Count < 2 && clock.Elapsed < TimeSpan.FromSeconds(5))
        {
            await Task.Delay(20);
        }
        Assert.Equal(2, server.Seen.Count);
        await cancel.CancelAsync();
        Exception failure = await Assert.ThrowsAnyAsync<Exception>(() => reading);

        Assert.IsAssignableFrom<OperationCanceledException>(failure);
        Assert.IsNotType<NetworkTimeoutException>(failure);
        Assert.True(
            clock.Elapsed < TimeSpan.FromSeconds(7),
            "the cancelled iteration stops promptly"
        );
    }

