    public async Task BhvPagination022ARefreshedCredentialIsUsedForTheNextPage()
    {
        using PagedServer server = CatalogServer(3, 1);
        PetApi api = PetApiFor(server, authenticator: new RotatingAuthenticator());

        _ = await NamesAsync(api.ListPetCatalogPagesAsync());

        Assert.Equal("Bearer t1", server.Seen[0].Header("Authorization"));
        Assert.Equal("Bearer t2", server.Seen[1].Header("Authorization"));
        Assert.Equal("Bearer t3", server.Seen[2].Header("Authorization"));
    }

    [Fact]
    public async Task BhvPagination023AnErrorFromALinkDrivenPageRequestCarriesThePathWithoutTheQuery()
    {
        using PagedServer server = new(
            (request, _) =>
                request.Param("page") is not null
                    ? new Reply(500, "{}")
                    : Reply.Ok(
                        "[" + PetJson("f0") + "]",
                        new Dictionary<string, string>
                        {
                            ["Link"] = "</pet/feed?page=1&secret=s3>; rel=\"next\"",
                        }
                    )
        );

        await using IAsyncEnumerator<Pet> items = PetApiFor(server)
            .ListPetFeedPagesAsync()
            .GetAsyncEnumerator();
        Assert.True(await items.MoveNextAsync());
        Assert.Equal("f0", items.Current.Name);
        ApiException failure = await Assert.ThrowsAsync<InternalServerErrorException>(() =>
            items.MoveNextAsync().AsTask()
        );

        Assert.Equal(500, failure.StatusCode);
        Assert.Equal("/pet/feed", failure.RequestPath);
        Assert.DoesNotContain("s3", failure.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void BhvPagination024AnOperationWithTwoCandidateCursorsTwoArrayPropertiesANonGetMethodOrSeveral2xxBodiesGetsNoPagedMethod()
    {
        HashSet<string> paged =
        [
            .. typeof(PetApi)
                .GetMethods()
                .Select(m => m.Name)
                .Where(n => n.EndsWith("PagesAsync", StringComparison.Ordinal)),
        ];

        Assert.Equal(
            new HashSet<string>
            {
                "ListPetCatalogPagesAsync",
                "ListPetEventsPagesAsync",
                "ListPetFeedPagesAsync",
                "ListPetNotesPagesAsync",
                "ListPetOffsetsPagesAsync",
                "ListPetPageNumbersPagesAsync",
                "ListPetsAfterPagesAsync",
                "ListPetNextUrlPagesAsync",
            },
            paged
        );
        Assert.Contains(typeof(PetApi).GetMethods(), m => m.Name == "ListPetMatchesAsync");
    }

    [Fact]
    public void BhvPagination025APagedMethodHasTheSameParametersInTheSameOrderAsTheBaseMethodAndTheBaseMethodIsUnchanged()
    {
        foreach (
            System.Reflection.MethodInfo pages in typeof(PetApi)
                .GetMethods()
                .Where(m => m.Name.EndsWith("PagesAsync", StringComparison.Ordinal))
        )
        {
            string baseName = pages.Name[..^"PagesAsync".Length] + "Async";
            System.Reflection.MethodInfo buffered = Assert.Single(
                typeof(PetApi).GetMethods(),
                m =>
                    m.Name == baseName
                    && m.GetParameters()
                        .Select(p => p.ParameterType)
                        .SequenceEqual(pages.GetParameters().Select(p => p.ParameterType))
            );

            Assert.False(
                buffered.ReturnType.IsGenericType
                    && buffered
                        .ReturnType.GetGenericArguments()[0]
                        .Name.StartsWith("Paginator", StringComparison.Ordinal)
            );
            Assert.Equal(typeof(Task<>), buffered.ReturnType.GetGenericTypeDefinition());
        }
    }

    [Fact]
    public void BhvPagination026TheGeneratorOptionOverridesInferenceAndCanSwitchAnOperationOrTheWholeFeatureOff()
    {
        HashSet<string> names = [.. typeof(PetApi).GetMethods().Select(m => m.Name)];

        Assert.Contains("ListPetEventsPagesAsync", names);
        Assert.DoesNotContain("ListPetArchivePagesAsync", names);
        Assert.Contains("ListPetArchiveAsync", names);
    }

    [Fact]
    public async Task BhvPagination027HeadersAndOptionsGivenToThePagedMethodAreSentOnEveryPageRequest()
    {
        using PagedServer server = SameOriginFeed(3);

        _ = await NamesAsync(
            PetApiFor(server)
                .ListPetFeedPagesAsync(
                    new ListPetFeedOptions
                    {
                        Limit = 1,
                        Headers = new Dictionary<string, string> { ["X-Keep"] = "yes" },
                    }
                )
