    [Fact]
    public async Task BhvPagination028TheCursorForTheNextPageIsTakenFromTheAcceptedResponseNeverFromARetriedAttempt()
    {
        using PagedServer server = new(
            (request, number) =>
                number == 1
                    ? new Reply(
                        503,
                        "{\"items\":[],\"next_cursor\":\"WRONG\"}",
                        new Dictionary<string, string> { ["Retry-After"] = "0" }
                    )
                    : Reply.Ok(CatalogBody(request.Param("cursor") is null ? 0 : 1, 1, 2))
        );

        Assert.Equal(
            ["p0-0", "p1-0"],
            await NamesAsync(PetApiFor(server, maxRetries: 2).ListPetCatalogPagesAsync())
        );
        Assert.Equal(new List<string?> { null, null, "c1" }, ParamsSeen(server, "cursor"));
    }

    [Fact]
    public async Task BhvPagination029ANextUrlInTheBodyIsFollowedAndANextUrlOnAnotherOriginIsRefused()
    {
        using PagedServer server = NextUrlServer(3);
        Assert.Equal(
            ["f0", "f1", "f2"],
            await NamesAsync(PetApiFor(server).ListPetNextUrlPagesAsync())
        );
        Assert.Equal(new List<string?> { null, "1", "2" }, ParamsSeen(server, "p"));

        using PagedServer elsewhere = new(
            (_, _) => Reply.Ok("{\"items\":[" + PetJson("stolen") + "]}")
        );
        using PagedServer origin = new(
            (_, _) =>
                Reply.Ok(
                    "{\"items\":["
                        + PetJson("f0")
                        + "],\"next_url\":\""
                        + elsewhere.Url
                        + "/pet/next?p=1\"}"
                )
        );
        await using IAsyncEnumerator<Pet> items = PetApiFor(origin)
            .ListPetNextUrlPagesAsync()
            .GetAsyncEnumerator();
        Assert.True(await items.MoveNextAsync());
        Assert.Equal("f0", items.Current.Name);
        PaginationException refused = await Assert.ThrowsAsync<PaginationException>(() =>
            items.MoveNextAsync().AsTask()
        );

        Assert.DoesNotContain("p=1", refused.Message, StringComparison.Ordinal);
        Assert.Empty(elsewhere.Seen);
    }

    [Fact]
    public void BhvPagination030AVendorExtensionOnAnOperationIsReadAsAHintAndTheOverrideOptionWinsOverIt()
    {
        Assert.Contains(typeof(PetApi).GetMethods(), m => m.Name == "ListPetNotesPagesAsync");
    }

    [Fact]
    public async Task BhvPagination031TheRepeatedCursorFailureIsAPaginationErrorAndIsNotANetworkErrorOrAnApiError()
    {
        Assert.Equal(typeof(OpenAPIException), typeof(PaginationException).BaseType);
        using PagedServer server = new((_, _) => Reply.Ok("{\"items\":[],\"next_cursor\":\"c1\"}"));

        OpenAPIException failure = await Assert.ThrowsAnyAsync<OpenAPIException>(() =>
            NamesAsync(
                PetApiFor(server)
                    .ListPetCatalogPagesAsync(new ListPetCatalogOptions { Cursor = "c1" })
            )
        );

        Assert.IsType<PaginationException>(failure);
        Assert.IsNotAssignableFrom<ApiException>(failure);
        Assert.IsNotAssignableFrom<NetworkException>(failure);
    }

    [Fact]
    public void BhvPagination032AnOperationThatIsStreamedIsNeverAlsoGivenAPagedMethod()
    {
        Assert.DoesNotContain(
            typeof(StoreApi).GetMethods(),
            m => m.Name.EndsWith("PagesAsync", StringComparison.Ordinal)
        );
        Assert.Contains(typeof(StoreApi).GetMethods(), m => m.Name == "ExportOrdersStreamAsync");
    }

    /* D189: the opt-in check of a request body against the validation keywords of its schema. */
    private static readonly AllowanceTier ValidTier = new() { Level = 0, Name = "ab" };

    private static readonly Allowance ValidAllowance = new()
    {
        Label = "abc",
        Count = 5,
        Ratio = 0.5,
        Step = 10,
        Codes = ["a"],
        Limits = new() { ["a"] = 1 },
        Tier = ValidTier,
        Parts = [ValidTier],
    };

    private static readonly (
        string Keyword,
        Allowance Body,
        string Message
    )[] ConstraintViolations =
    [
        (
            "minLength",
            ValidAllowance with
            {
                Label = "a",
            },
            "Invalid request body: label must be at least 2 characters long"
        ),
        (
            "maxLength",
            ValidAllowance with
            {
                Label = "abcdef",
            },
            "Invalid request body: label must be at most 5 characters long"
        ),
        (
            "pattern",
            ValidAllowance with
            {
                Label = "ab1",
            },
            "Invalid request body: label must match the pattern ^[a-z]+$"
        ),
        (
            "minimum",
            ValidAllowance with
            {
                Count = 0,
            },
            "Invalid request body: count must be greater than or equal to 1"
        ),
        (
            "maximum",
            ValidAllowance with
            {
                Count = 11,
            },
            "Invalid request body: count must be less than or equal to 10"
        ),
        (
            "exclusiveMinimum",
            ValidAllowance with
            {
                Ratio = 0.0,
            },
            "Invalid request body: ratio must be greater than 0"
        ),
        (
            "exclusiveMaximum",
            ValidAllowance with
            {
                Ratio = 1.0,
            },
            "Invalid request body: ratio must be less than 1"
        ),
        (
            "multipleOf",
            ValidAllowance with
            {
                Step = 7,
            },
            "Invalid request body: step must be a multiple of 5"
        ),
        (
            "minItems",
            ValidAllowance with
            {
                Codes = [],
            },
            "Invalid request body: codes must have at least 1 items"
        ),
        (
            "maxItems",
            ValidAllowance with
            {
                Codes = ["a", "b", "c", "d"],
            },
            "Invalid request body: codes must have at most 3 items"
        ),
        (
            "minProperties",
            ValidAllowance with
            {
                Limits = [],
            },
            "Invalid request body: limits must have at least 1 properties"
        ),
        (
            "maxProperties",
            ValidAllowance with
            {
                Limits = new()
                {
                    ["a"] = 1,
                    ["b"] = 2,
                    ["c"] = 3,
                },
            },
            "Invalid request body: limits must have at most 2 properties"
        ),
    ];

    private static StoreApi ConstraintApi(ScriptedApiClient client, bool validateConstraints)
    {
        return new StoreApi(
            client,
            Configuration
                .Builder()
                .BaseUrl("http://localhost")
                .ValidateConstraints(validateConstraints)
                .Build()
        );
    }

    [Fact]
    public async Task BhvModels706ConstraintValidationIsOffByDefault()
    {
        var client = new ScriptedApiClient(204);
        var api = new StoreApi(client, Configuration.Builder().BaseUrl("http://localhost").Build());

        await api.SubmitAllowanceAsync(ValidAllowance with { Label = "a", Count = 0 });

        Assert.False(Configuration.DefaultConfiguration().ValidateConstraints);
        Assert.Single(client.Sent);
    }

    [Fact]
    public async Task BhvModels707ABodyThatBreaksOneKeywordIsRefusedBeforeItIsSent()
    {
        foreach (var (_, body, message) in ConstraintViolations)
        {
            var client = new ScriptedApiClient(204);

            ArgumentException refused = await Assert.ThrowsAsync<ArgumentException>(() =>
                ConstraintApi(client, true).SubmitAllowanceAsync(body)
            );

            Assert.Equal(message, refused.Message);
            Assert.Empty(client.Sent);
        }
    }

    [Fact]
    public async Task BhvModels708AViolationInsideAHeldModelOrAListNamesItsPath()
    {
        var client = new ScriptedApiClient(204);
        AllowanceTier ok = new() { Level = 1, Name = "ab" };
        AllowanceTier negative = new() { Level = -1 };

        ArgumentException held = await Assert.ThrowsAsync<ArgumentException>(() =>
            ConstraintApi(client, true)
                .SubmitAllowanceAsync(ValidAllowance with { Tier = negative })
        );
        ArgumentException listed = await Assert.ThrowsAsync<ArgumentException>(() =>
            ConstraintApi(client, true)
                .SubmitAllowanceAsync(ValidAllowance with { Parts = [ok, negative] })
        );
        ArgumentException named = await Assert.ThrowsAsync<ArgumentException>(() =>
            ConstraintApi(client, true)
                .SubmitAllowanceAsync(ValidAllowance with { Tier = ok with { Name = "abcd" } })
        );

        Assert.Equal(
            "Invalid request body: tier.level must be greater than or equal to 0",
            held.Message
        );
        Assert.Equal(
            "Invalid request body: parts[1].level must be greater than or equal to 0",
            listed.Message
        );
        Assert.Equal(
            "Invalid request body: tier.name must be at most 3 characters long",
            named.Message
        );
        Assert.Empty(client.Sent);
    }

    [Fact]
    public async Task BhvModels709ABodyWithinEveryConstraintIsSentAndANullValueIsNotChecked()
    {
        var client = new ScriptedApiClient(204);
        StoreApi api = ConstraintApi(client, true);

        await api.SubmitAllowanceAsync(ValidAllowance);
        Assert.Single(client.Sent);
        await api.SubmitAllowanceAsync(new Allowance());
        await api.SubmitAllowanceAsync(new Allowance { Tier = new AllowanceTier() });

        Assert.Equal(3, client.Sent.Count);
    }
}
